-- ETAPA 23: sensitive incident domain. No diagnoses or legal conclusions are modeled.
create table public.incidents (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,reference_code text not null,reported_at timestamptz not null default now(),occurred_at timestamptz,site_id uuid references public.sites(id) on delete set null,classification text not null check(classification in ('incident','work_accident','occupational_disease_report','near_miss')),status text not null default 'reported' check(status in ('reported','under_investigation','actions_open','closed','cancelled')),summary text not null check(btrim(summary)<>''),reported_by uuid references auth.users(id) on delete set null,closed_at timestamptz,closed_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,reference_code));
create table public.incident_sensitive_details (incident_id uuid primary key references public.incidents(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,affected_person_reference text,restricted_description text,health_information_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.incident_people (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,incident_id uuid not null references public.incidents(id) on delete restrict,organization_member_id uuid references public.organization_members(id) on delete set null,role text not null check(role in ('affected_person','witness','reporter','investigator')),display_reference text,created_at timestamptz not null default now());
create table public.incident_investigations (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,incident_id uuid not null references public.incidents(id) on delete restrict,status text not null default 'open' check(status in ('open','reviewed','closed')),methodology_note text,started_at timestamptz not null default now(),completed_at timestamptz,lead_user_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(incident_id));
create table public.incident_causes (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,incident_investigation_id uuid not null references public.incident_investigations(id) on delete restrict,cause_type text not null check(cause_type in ('immediate','basic','contributing')),description text not null check(btrim(description)<>''),created_at timestamptz not null default now());
create table public.incident_actions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,incident_id uuid not null references public.incidents(id) on delete restrict,improvement_action_id uuid references public.improvement_actions(id) on delete set null,title text not null check(btrim(title)<>''),status text not null default 'open' check(status in ('open','in_progress','verified','cancelled')),due_at date,responsible_user_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.incident_evidences (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,incident_id uuid not null references public.incidents(id) on delete restrict,document_version_id uuid not null references public.document_versions(id) on delete restrict,visibility text not null default 'restricted' check(visibility in ('restricted','sensitive')),created_at timestamptz not null default now(),unique(incident_id,document_version_id));
create table public.incident_communications (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,incident_id uuid not null references public.incidents(id) on delete restrict,communication_type text not null check(communication_type in ('internal','authority_preparation','insurer_preparation','other')),status text not null default 'draft' check(status in ('draft','prepared','sent','cancelled')),document_version_id uuid references public.document_versions(id) on delete restrict,created_at timestamptz not null default now());
create table public.incident_export_templates (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,code text not null,title text not null,version text not null,status text not null default 'draft' check(status in ('draft','reviewed','approved','archived')),document_version_id uuid references public.document_versions(id) on delete restrict,created_at timestamptz not null default now(),unique(organization_id,code,version));
create index incidents_org_status_idx on public.incidents(organization_id,status,reported_at desc); create index incident_people_incident_idx on public.incident_people(incident_id); create index incident_actions_incident_idx on public.incident_actions(incident_id,status); create index incident_evidences_incident_idx on public.incident_evidences(incident_id);
insert into public.permissions(code,module,action,description) values ('incidents.read','incidents','read','Consultar casos de incidentes sin detalle sensible.'),('incidents.manage','incidents','manage','Reportar e investigar incidentes.'),('incidents.sensitive','incidents','sensitive','Consultar detalle sensible y evidencia sensible.'),('incidents.close','incidents','close','Cerrar casos e investigaciones.') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.code in ('incidents.read','incidents.manage','incidents.sensitive','incidents.close') where r.code='organization_admin' and r.organization_id is null on conflict do nothing;
create or replace function private.validate_incident_links() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if tg_table_name='incident_sensitive_details' and not exists(select 1 from public.incidents where id=new.incident_id and organization_id=new.organization_id) then raise exception 'incident detail belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='incident_people' and (not exists(select 1 from public.incidents where id=new.incident_id and organization_id=new.organization_id) or (new.organization_member_id is not null and not exists(select 1 from public.organization_members where id=new.organization_member_id and organization_id=new.organization_id))) then raise exception 'incident person belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='incident_investigations' and not exists(select 1 from public.incidents where id=new.incident_id and organization_id=new.organization_id) then raise exception 'incident investigation belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='incident_causes' and not exists(select 1 from public.incident_investigations where id=new.incident_investigation_id and organization_id=new.organization_id) then raise exception 'incident cause belongs to another organization' using errcode='23514'; end if;
 if tg_table_name in ('incident_actions','incident_evidences','incident_communications') and not exists(select 1 from public.incidents where id=new.incident_id and organization_id=new.organization_id) then raise exception 'incident resource belongs to another organization' using errcode='23514'; end if;
 if tg_table_name in ('incident_evidences','incident_communications','incident_export_templates') and new.document_version_id is not null and not exists(select 1 from public.document_versions where id=new.document_version_id and organization_id=new.organization_id) then raise exception 'incident evidence belongs to another organization' using errcode='23514'; end if; return new; end; $$;
revoke all on function private.validate_incident_links() from public,anon,authenticated,service_role;
alter table public.incidents enable row level security; alter table public.incident_sensitive_details enable row level security; alter table public.incident_people enable row level security; alter table public.incident_investigations enable row level security; alter table public.incident_causes enable row level security; alter table public.incident_actions enable row level security; alter table public.incident_evidences enable row level security; alter table public.incident_communications enable row level security; alter table public.incident_export_templates enable row level security;
grant select,insert,update on public.incidents,public.incident_people,public.incident_investigations,public.incident_causes,public.incident_actions,public.incident_communications,public.incident_export_templates to authenticated; grant select,insert on public.incident_evidences,public.incident_sensitive_details to authenticated;
create policy incidents_read on public.incidents for select to authenticated using((select private.has_permission(organization_id,'incidents.read'))); create policy incidents_manage on public.incidents for all to authenticated using((select private.has_permission(organization_id,'incidents.manage'))) with check((select private.has_permission(organization_id,'incidents.manage')));
create policy incident_sensitive_read on public.incident_sensitive_details for select to authenticated using((select private.has_permission(organization_id,'incidents.sensitive'))); create policy incident_sensitive_write on public.incident_sensitive_details for insert to authenticated with check((select private.has_permission(organization_id,'incidents.sensitive')));
create policy incident_related_read on public.incident_people for select to authenticated using((select private.has_permission(organization_id,'incidents.read'))); create policy incident_related_write on public.incident_people for all to authenticated using((select private.has_permission(organization_id,'incidents.manage'))) with check((select private.has_permission(organization_id,'incidents.manage')));
create policy investigations_read on public.incident_investigations for select to authenticated using((select private.has_permission(organization_id,'incidents.read'))); create policy investigations_write on public.incident_investigations for all to authenticated using((select private.has_permission(organization_id,'incidents.manage'))) with check((select private.has_permission(organization_id,'incidents.manage')));
create policy causes_read on public.incident_causes for select to authenticated using((select private.has_permission(organization_id,'incidents.read'))); create policy causes_write on public.incident_causes for all to authenticated using((select private.has_permission(organization_id,'incidents.manage'))) with check((select private.has_permission(organization_id,'incidents.manage')));
create policy incident_actions_read on public.incident_actions for select to authenticated using((select private.has_permission(organization_id,'incidents.read'))); create policy incident_actions_write on public.incident_actions for all to authenticated using((select private.has_permission(organization_id,'incidents.manage'))) with check((select private.has_permission(organization_id,'incidents.manage')));
create policy incident_evidences_read on public.incident_evidences for select to authenticated using((select private.has_permission(organization_id,case when visibility='sensitive' then 'incidents.sensitive' else 'incidents.read' end))); create policy incident_evidences_insert on public.incident_evidences for insert to authenticated with check((select private.has_permission(organization_id,'incidents.manage')));
create policy incident_communications_read on public.incident_communications for select to authenticated using((select private.has_permission(organization_id,'incidents.read'))); create policy incident_communications_write on public.incident_communications for all to authenticated using((select private.has_permission(organization_id,'incidents.manage'))) with check((select private.has_permission(organization_id,'incidents.manage')));
create policy incident_templates_read on public.incident_export_templates for select to authenticated using((select private.has_permission(organization_id,'incidents.read'))); create policy incident_templates_write on public.incident_export_templates for all to authenticated using((select private.has_permission(organization_id,'incidents.manage'))) with check((select private.has_permission(organization_id,'incidents.manage')));
create trigger incident_sensitive_links before insert or update on public.incident_sensitive_details for each row execute function private.validate_incident_links(); create trigger incident_people_links before insert or update on public.incident_people for each row execute function private.validate_incident_links(); create trigger investigation_links before insert or update on public.incident_investigations for each row execute function private.validate_incident_links(); create trigger cause_links before insert or update on public.incident_causes for each row execute function private.validate_incident_links(); create trigger action_links before insert or update on public.incident_actions for each row execute function private.validate_incident_links(); create trigger evidence_links before insert on public.incident_evidences for each row execute function private.validate_incident_links(); create trigger communication_links before insert or update on public.incident_communications for each row execute function private.validate_incident_links();
create trigger incidents_audit after insert or update on public.incidents for each row execute function private.capture_core_audit(); create trigger incident_sensitive_audit after insert on public.incident_sensitive_details for each row execute function private.capture_core_audit(); create trigger incident_evidence_audit after insert on public.incident_evidences for each row execute function private.capture_core_audit(); create trigger incident_actions_audit after insert or update on public.incident_actions for each row execute function private.capture_core_audit(); notify pgrst,'reload schema';
